target.css:
:root {
  --bg: #fffbf4;
  --border: #e8c9a0;
  --header-bg: #f4e2c8;
  --accent: #c8704a;
  --accent-light: #f7ede0;
  --text-primary: #3b2412;
  --text-secondary: #7a5030;
  --badge-bg: #c8704a;
  --badge-text: #ffffff;
  --dot: #c8704a;
  --line: #e8c9a0;
  --label: #a07050;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  margin: 0;
}

.ticket {
  background: var(--bg);
  border: 2px solid var(--border);
  border-radius: 16px;
  width: 380px;
  overflow: hidden;
}

.ticket-header {
  background: var(--header-bg);
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px 20px;
}

.ticket-emoji {
  font-size: 36px;
  line-height: 1;
}

.ticket-title-group {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.ticket-title {
  margin: 0;
  font-size: 20px;
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1.2;
}

.ticket-subtitle {
  margin: 0;
  font-size: 12px;
  color: var(--text-secondary);
  font-weight: 500;
}

.ticket-divider {
  display: flex;
  align-items: center;
  gap: 0;
  padding: 0 20px;
  border-top: 1px dashed var(--line);
  border-bottom: 1px dashed var(--line);
  height: 16px;
  background: var(--accent-light);
}

.divider-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--dot);
  flex-shrink: 0;
}

.divider-line {
  flex: 1;
  height: 1px;
  background: var(--line);
  margin: 0 6px;
}

.ticket-body {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 16px 20px;
}

.ticket-detail {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.detail-label {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--label);
}

.detail-value {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-primary);
}

.ticket-footer {
  background: var(--header-bg);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 20px;
  border-top: 1px solid var(--border);
}

.ticket-badge {
  background: var(--badge-bg);
  color: var(--badge-text);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.1em;
  padding: 4px 10px;
  border-radius: 20px;
}

.ticket-number {
  font-size: 12px;
  color: var(--text-secondary);
  font-weight: 500;
}

